using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageReceiptTests
{
    private const string ObjectSource = """
            [MessagePack.MessagePackObject]
            public class MyObject
            {
                [MessagePack.Key(0)]
                public int Value { get; set; }
            }
            """;

    private static async Task<Compilation> RunGeneratorAsync(string source, CSharpParseOptions parseOptions)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = new List<MetadataReference>(frameworkRefs);
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new ISourceGenerator[] { new MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        return output;
    }

    [Fact]
    public async Task UserAnnotatedResolver_DoesNotProduceDuplicateAttribute()
    {
        string source = """
            namespace MyNs
            {
                [System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]
                [MessagePack.GeneratedMessagePackResolver]
                partial class MyResolver { }
            }

            """ + ObjectSource;
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3);
        Compilation output = await RunGeneratorAsync(source, parseOptions);
        List<Diagnostic> duplicates = output.GetDiagnostics().Where(d => d.Id == "CS0579").ToList();
        Assert.True(duplicates.Count == 0, string.Join(Environment.NewLine, duplicates.Select(d => d.ToString())));
    }

    [Fact]
    public async Task NetStandard20Consumer_ResolverIsStillExcludedFromCoverage()
    {
        string source = """
            namespace MyNs
            {
                [MessagePack.GeneratedMessagePackResolver]
                partial class MyResolver { }
            }

            """ + ObjectSource;
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: new[] { "NETSTANDARD2_0" });
        Compilation output = await RunGeneratorAsync(source, parseOptions);
        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("MyNs.MyResolver");
        Assert.NotNull(resolver);
        bool hasAttribute = resolver!.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute");
        Assert.True(hasAttribute, "Generated resolver should carry ExcludeFromCodeCoverage on netstandard2.0, where the attribute exists.");
    }
}
